components.css:
.ds-specimen { font-family: IBM Plex Sans, sans-serif; color: var(--slate-12, #1c2024); }
.ds-explorer-actions{
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 8px;
}
.ds-explorer-actions a{
    background: var(--indigo-9, #3e63dd);
    color: var(--indigo-1, #fdfdfe);
    padding: 12px 18px;
    border-radius: 4px;
    font-size: 12px;
    min-height: 44px;
}
.ds-explorer-actions button{
    font-size: 12px;
    color: var(--slate-11, #60646c);
    min-height: 40px;
    cursor: pointer;
}
.ds-explorer-actions{
        flex-direction: row;
        align-items: center;
        gap: 16px;
    }
.ds-explorer-actions a{
    color: #fdfdfe;
}
.ds-specimen :focus-visible { outline: 2px solid var(--indigo-8, #8da4ef); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }

.ds-specimen { font-family: IBM Plex Sans, sans-serif; color: var(--slate-12, #1c2024); }
.ds-explorer-search{
    display: flex;
    align-items: center;
    gap: 12px;
    flex: 1;
    min-width: 180px;
}
.ds-explorer-search > span{
    color: var(--slate-11, #60646c);
    font-size: 12px;
}
.ds-explorer-search input{
    width: 100%;
    min-width: 0;
    padding: 10px 0;
    background: transparent;
    border: 0;
    font-size: 16px;
    color: var(--slate-12, #1c2024);
}
.ds-explorer-search input::placeholder{
    color: var(--slate-11, #60646c);
}
.ds-explorer-search{
        flex-basis: 100%;
    }
.ds-specimen :focus-visible { outline: 2px solid var(--indigo-8, #8da4ef); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }

.ds-specimen { font-family: IBM Plex Sans, sans-serif; color: var(--slate-12, #1c2024); }
.ds-explorer-categories{
    display: flex;
    gap: 4px;
}
.ds-explorer-categories button{
    min-height: 44px;
    padding: 10px 14px;
    font-size: 12px;
    border: 0;
    border-radius: 4px;
    color: var(--slate-11, #60646c);
    background: transparent;
    cursor: pointer;
}
.ds-explorer-categories [aria-pressed="true"]{
    background: var(--indigo-4, #e1e9ff);
    color: var(--indigo-11, #3a5bc7);
}
.ds-explorer-categories button:hover{
    background: var(--slate-3, #f0f0f3);
    color: var(--slate-12, #1c2024);
}
.ds-explorer-categories{
        flex: 1;
    }
.ds-explorer-categories{
        flex-basis: 100%;
    }
.ds-explorer-categories button{
        flex: 1;
        padding-inline: 8px;
    }
.ds-specimen :focus-visible { outline: 2px solid var(--indigo-8, #8da4ef); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }

.ds-specimen { font-family: IBM Plex Sans, sans-serif; color: var(--slate-12, #1c2024); }
.ds-explorer-item{
    width: 100%;
    display: flex;
    align-items: center;
    gap: 12px;
    text-align: left;
    min-height: 72px;
    padding: 12px;
    border: 0;
    border-bottom: 0.5px solid var(--slate-6, #d9d9e0);
    background: transparent;
    color: var(--slate-12, #1c2024);
    cursor: pointer;
    border-radius: 0;
}
.ds-explorer-item:hover{
    background: var(--slate-3, #f0f0f3);
}
.ds-explorer-item[aria-pressed="true"]{
    background: var(--indigo-3, #edf2fe);
}
.ds-explorer-item > span:nth-child(2){
    flex: 1;
    min-width: 0;
}
.ds-explorer-item strong{
    display: block;
    font-size: 16px;
    font-weight: 500;
    overflow-wrap: anywhere;
}
.ds-explorer-item small{
    display: block;
    font-size: 12px;
    color: var(--slate-11, #60646c);
    overflow-wrap: anywhere;
    margin-top: 4px;
}
.ds-explorer-item > svg{
    flex-shrink: 0;
    color: var(--slate-11, #60646c);
}
.ds-explorer-item{
        flex: 0 0 200px;
        border: 0.5px solid var(--slate-6, #d9d9e0);
        padding: 10px;
    }
.ds-explorer-item > svg{
        display: none;
    }
.ds-specimen :focus-visible { outline: 2px solid var(--indigo-8, #8da4ef); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }

.ds-specimen { font-family: IBM Plex Sans, sans-serif; color: var(--slate-12, #1c2024); }
.ds-explorer-tags{
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    grid-column: 1 / -1;
}
.ds-explorer-tags button{
    font-size: 12px;
    padding: 6px 10px;
    background: var(--slate-3, #f0f0f3);
    color: var(--slate-11, #60646c);
    border-radius: 3px;
    min-height: 32px;
}
.ds-specimen :focus-visible { outline: 2px solid var(--indigo-8, #8da4ef); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }
